// Extract text content and compare with historical data
const html = $input.first().json.data;
const textContent = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 5000);

// Get yesterday's data from n8n static storage
const workflowStaticData = getWorkflowStaticData('global');
const previousContent = workflowStaticData.competitorContent || 'No previous data';

// Check for changes
const hasChanged = previousContent !== textContent;

// Save today's content for tomorrow's comparison
workflowStaticData.competitorContent = textContent;

return [{
  json: {
    currentContent: textContent,
    previousContent: hasChanged ? previousContent : null,
    hasChanges: hasChanged,
    competitorUrl: $('Scrape Competitor Website').item.json.url || $env.COMPETITOR_URL
  }
}];

